const app=document.querySelector('#app'),cartDialog=document.querySelector('#cart-dialog'),contentDialog=document.querySelector('#content-dialog');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+Number(n).toFixed(2),asset=n=>'assets/'+n+'.webp',getProduct=id=>PRODUCTS.find(p=>p.id===id);
const icons={search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',cart:'<path d="M2 3h3l3 12h11l3-9H7M9 5V1m-3 2 3 3 3-3"/><circle cx="10" cy="20" r="1"/><circle cx="18" cy="20" r="1"/>',account:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-3a7 7 0 0 1 14 0v3Z"/>',menu:'<path d="M3 5h18M3 12h18M3 19h18"/>',monitor:'<rect x="2" y="3" width="20" height="14" rx="1"/><path d="M8 22h8m-4-5v5"/>',chip:'<rect x="5" y="5" width="14" height="14" rx="1"/><path d="M9 1v4m6-4v4M9 19v4m6-4v4M1 9h4m-4 6h4m14-6h4m-4 6h4"/>',night:'<path d="M15 2a9 9 0 1 0 7 14A9 9 0 0 1 15 2ZM2 2v6h6"/>',cable:'<path d="M6 3v10a3 3 0 0 0 6 0V8a3 3 0 0 1 6 0v13M3 1h6v4H3Zm12 18h6v4h-6Z"/>',cloud:'<path d="M6 18a5 5 0 1 1 0-10 6 6 0 0 1 12-1 5 5 0 1 1 1 11Z"/><path d="m9 12 3 3 5-5"/>',shield:'<path d="m12 2 9 4v7c0 5-9 9-9 9S3 18 3 13V6Z"/><path d="m8 12 3 3 5-6"/>',filter:'<path d="M3 5h18M6 12h12M9 19h6"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 18h4"/>'};
const icon=n=>'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+(icons[n]||icons.shield)+'</svg>';
const logo='<svg viewBox="0 0 28 32" aria-hidden="true"><path d="m14 1 11 6v8l-5 3v-8l-6-3-6 3v12l6 3 6-3 5 3-11 6-11-6V7Z"/><path d="m14 11 5 3-5 3-5-3Z"/></svg><span>AMCREST</span>';
let cart=[],currentRoute='',selectedColor='White',productQty=1,selectedPhoto='camera-front',billing='monthly',detailTab='Details',compare=[],mobileMenu=false,navPanel='',accountName='Celine',accountSignedOut=false;
const filterState={res:new Set(),types:new Set(),features:new Set(),min:0,max:699,rating:0};
try{const saved=JSON.parse(localStorage.getItem('amcrest-demo-cart')||'[]');cart=Array.isArray(saved)?saved.filter(x=>getProduct(x.id)&&Number.isFinite(+x.qty)).map(x=>({id:x.id,color:x.color==='Black'?'Black':'White',qty:Math.max(1,Math.min(99,Math.round(+x.qty)))})):[];accountName=localStorage.getItem('amcrest-demo-name')||'Celine';}catch{}
const announce=text=>document.querySelector('#announcement').textContent=text;
const cartCount=()=>cart.reduce((s,i)=>s+i.qty,0),cartTotal=()=>cart.reduce((s,i)=>s+getProduct(i.id).price*i.qty,0);
function saveCart(){try{localStorage.setItem('amcrest-demo-cart',JSON.stringify(cart));}catch{}document.querySelectorAll('[data-cart-count]').forEach(el=>{el.textContent=cartCount();el.hidden=!cartCount();});document.querySelector('[data-cart-open]')?.setAttribute('aria-label','Open cart, '+cartCount()+' items');}
function readRoute(){const raw=location.hash.replace(/^#\/?/,'')||'home';const [path,query]=raw.split('?');return {path,params:new URLSearchParams(query||'')};}
function link(path){return '#/'+path;}
function primary(text,path,cls=''){return '<a class="button '+cls+'" href="'+link(path)+'">'+text+'</a>';}
function header(path){return (path==='home'?'<div class="shipping">Free Shipping on All Orders Over $99 — Limited Time Only <a href="#/solutions">Shop Now</a></div>':'')+`<header class="header"><div class="nav-inner"><button class="mobile-menu-button icon-button" data-action="mobile-menu" aria-label="Open menu">${icon('menu')}</button><a class="brand" href="#/home" aria-label="Amcrest home">${logo}</a><nav class="nav-links" aria-label="Main navigation"><button data-action="products-menu" aria-expanded="false" aria-controls="products-panel" ${['solutions','category','product'].includes(path)?'class="active"':''}>Products</button><a href="#/cloud" class="${path==='cloud'?'active':''}">Services</a><a href="#/support" class="${path==='support'?'active':''}">Support</a></nav><div class="nav-tools"><button class="icon-button" data-action="search-menu" aria-label="Open search" aria-expanded="false">${icon('search')}</button><button class="icon-button" data-cart-open aria-label="Open cart, ${cartCount()} items">${icon('cart')}<span class="cart-count" data-cart-count ${cartCount()?'':'hidden'}>${cartCount()}</span></button><a class="icon-button account-button ${path==='account'?'active':''}" href="#/account" aria-label="My account">${icon('account')}</a></div></div><div id="products-panel" class="nav-panel" hidden>${megaMenu()}</div><div id="search-panel" class="nav-panel search-panel" hidden><div class="wrap"><form id="search-form" class="search-row"><label class="sr-only" for="product-search">Search products, guides, FAQs</label><input id="product-search" type="search" placeholder="Search products, guides, FAQs…" autocomplete="off"><button type="submit">Search</button><button type="button" data-action="close-menu" aria-label="Close search">×</button></form><div class="search-suggestions">RECENT <div><button data-search="4K PoE Camera">4K PoE Camera</button><button data-search="NVR">NVR</button><button data-search="Doorbell">Doorbell</button><button data-search="Indoor">Indoor</button></div></div><div id="search-results" class="search-results"></div></div></div></header>`;}
function megaMenu(){const groups=[['SECURITY CAMERAS',['PoE Cameras','WiFi Cameras','Analog Cameras','Thermal Cameras','PTZ Cameras','Dual-Lens Cameras']],['SYSTEMS & RECORDERS',['Complete Systems','NVR Recorders','DVR Recorders','NAS Storage']],['SMART HOME',['Smart Home Cameras','Video Doorbells','Baby Monitors','Webcams']],['GPS TRACKING',['GPS GL300','GPS GL310','GPS GV500']],['SMART MONITORS',['Smart Baby Monitor']],['WEBCAMS & AUDIO',['USB Webcams','Microphones']],['ACCESSORIES',['Mounts & Brackets','Cables & Connectors','Hard Drives & SD Cards']],['CERTIFIED REFURBISHED',['Certified Refurbished Cameras','Refurbished Systems']]];return '<div class="wrap"><div class="mega-grid">'+groups.map(([name,items])=>'<div><h4>'+name+'</h4>'+items.map(item=>'<a href="#/category?category='+encodeURIComponent(item)+'">'+item+'</a>').join('')+'</div>').join('')+'</div><div class="mega-all"><a href="#/category">View All Products ›</a></div></div>';}
function footer(){return `<footer class="footer"><div class="wrap"><a class="brand" href="#/home"><span>AMCREST</span></a><div class="footer-columns"><div><h4>ABOUT AMCREST</h4><button data-policy="Mission">Mission</button><button data-policy="Become a Dealer">Become a Dealer</button><div class="social-row"><button data-social="YouTube" aria-label="YouTube"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="1" y="5" width="22" height="15" rx="5" fill="currentColor"/><path d="m10 9 6 3-6 3Z" fill="#011835"/></svg></button><button data-social="Instagram" aria-label="Instagram"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2" y="2" width="20" height="20" rx="6" fill="none" stroke="currentColor" stroke-width="2.5"/><circle cx="12" cy="12" r="5" fill="none" stroke="currentColor" stroke-width="2.5"/><circle cx="18" cy="6" r="1.5" fill="currentColor"/></svg></button><button data-social="Facebook" aria-label="Facebook"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="11" fill="currentColor"/><path d="M14 5h3v4h-3v2h3l-1 4h-2v8h-4v-8H7v-4h3V9q0-4 4-4Z" fill="#011835"/></svg></button><button data-social="TikTok" aria-label="TikTok"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14 2h4c0 3 2 5 5 5v4a10 10 0 0 1-5-2v8a7 7 0 1 1-7-7v4a3 3 0 1 0 3 3Z" fill="currentColor"/></svg></button></div></div><div><h4>POLICIES</h4>${['Return','Shipping','Privacy','Terms & Conditions'].map(s=>'<button data-policy="'+s+'">'+s+'</button>').join('')}</div><div><h4>ARTICLES</h4><button data-action="buying-guide">Buying Guide</button><button data-action="buying-guide">PoE vs WiFi Cameras</button><a href="#/cloud">Cloud vs Local Storage</a><button data-action="buying-guide">Night Vision Explained</button><button data-action="buying-guide">Placement Tips</button></div></div><div class="footer-bottom"><span>Copyright © 2026 Amcrest Industries LLC. All rights reserved.</span><a href="../">Course redesign · Back to case study</a></div></div></footer>`;}
function contact(){return '<section class="contact"><div class="wrap"><h2>Talk to a Real Person</h2><div class="contact-grid">'+[['Live Chat','Average wait: under 2 min','Start Live Chat'],['Phone','1-888-212-7538','Call Now'],['Email','support@amcrest.com','Send Email']].map(([a,b,c])=>'<div><h3>'+a+'</h3><p>'+b+'</p><button class="button" data-contact="'+a+'">'+c+'</button></div>').join('')+'</div></div></section>';}
function productCard(p,options={}){const target=p.detail||p.id;return `<article class="product-card"><a class="product-image" href="#/product?id=${target}" aria-label="View ${esc(p.name)}">${p.tag?'<span class="tag">'+p.tag+'</span>':''}<img src="${asset(p.image)}" alt="${esc(p.name)}" loading="lazy" width="300" height="300">${p.purpose?'<span class="purpose">FOR '+p.purpose.toUpperCase()+'</span>':''}</a><div class="product-info">${options.category&&p.sku?'<span class="label">'+esc(p.sku)+'</span>':''}<h3><a href="#/product?id=${target}">${esc(p.name)}</a></h3>${p.reviews?'<div class="rating"><span class="stars" aria-label="'+p.rating+' out of 5 stars">'+('★'.repeat(p.rating)+'☆'.repeat(5-p.rating))+'</span><span class="review-count">('+p.reviews.toLocaleString()+')</span></div>':''}<div class="price">${money(p.price)}</div><button class="button" data-add="${p.id}">Add to Cart</button>${options.category?'<button class="compare-button" data-compare="'+p.id+'" aria-pressed="'+compare.includes(p.id)+'">'+(compare.includes(p.id)?'✓':'vs')+'</button>':''}</div></article>`;}
function featureBand(type='home',product=null){const data=type==='product'&&product&&product.id!=='camera'?[[product.resolution||product.type,'Product '+(product.resolution?'Resolution':'Type'),product.resolution||product.type],['chip','Features',product.features.join(' · ')||product.type],['shield','Your Solution',SCENARIOS.find(s=>s.id===product.scenario)?.name||product.category],['cable','Complete Your Setup','Explore accessories for your setup']]:type==='cloud'?[['cloud','Automatic Backup','Footage uploads as soon as motion is detected'],['phone','Watch Anywhere','Phone, tablet, or browser — your choice'],['shield','Bank-Level Security','256-bit AES encryption, end to end'],['cable','No Hardware Needed','No NVR, no hard drive — just your camera']]:type==='product'?[['4K','Ultra-Clear 4K','See every detail — faces, license plates, package labels'],['chip','Smart AI Alerts','Only notifies you for people & vehicles, not trees'],['night','Color Night Vision','Full-color footage up to 98 ft, even in total darkness'],['cable','One Cable Setup','PoE delivers power + data through a single Ethernet cable']]:[['4K','See Faces Clearly, Even at Night',''],['chip','Only Alerts You When It Matters',''],['5 min','Set Up in 5 Minutes, No Tools',''],['phone','Watch Live From Your Phone','']];return '<section class="trust-band"><div class="wrap">'+(type==='home'?'<h2 class="center">Why <em>500,000+</em> Homeowners Trust Amcrest</h2>':'')+'<div class="feature-icons">'+data.map(([i,h,p])=>'<div class="feature-icon"><div class="circle">'+(icons[i]?icon(i):i)+'</div><h4>'+h+'</h4>'+ (p?'<p>'+p+'</p>':'')+'</div>').join('')+'</div></div></section>';}
function videoButton(img,title,duration=''){return '<button class="video-button" data-preview="'+img+'" data-title="'+esc(title)+'" aria-label="Preview '+esc(title)+'"><img loading="lazy" src="'+asset(img)+'" alt="'+esc(title)+'"><span class="play" aria-hidden="true"></span>'+(duration?'<span class="duration">'+duration+'</span>':'')+'</button>';}
function home(){return `<section class="hero"><div class="wrap"><div class="hero-copy"><h1>See Everything.<br>Protect Everyone.</h1><p>Keep every family member safe with smart cameras you can check from anywhere — day or night.</p>${primary('Shop Now','solutions')}</div></div></section><section class="section"><div class="wrap"><h2 class="center">Find Your Solution</h2><div class="solution-cards">${SCENARIOS.map(s=>'<article class="solution-card"><img src="'+asset(s.image)+'" alt="'+s.name+'" loading="lazy"><div class="copy"><h3>'+s.name+'</h3><p>'+s.intro+'</p>'+primary('Shop Now','solutions?need='+s.id)+'</div></article>').join('')}</div><p class="need-help center">Not sure what I need? <button class="blue-link" data-action="buying-guide">Help Me Decide</button></p></div></section>${featureBand()}<section class="press"><div class="wrap"><p class="label center">AS SEEN IN</p><div class="press-logos">${['cnet','khou','safewise','safesmart','verge','ion','usatoday'].map(n=>'<img src="'+asset(n)+'" alt="'+n+'" loading="lazy">').join('')}<span class="press-text newswatch">NewsWatch</span><span class="press-text houzz">▰ houzz</span></div></div></section><section class="section gradient"><div class="wrap"><h2 class="center">Your Camera in Real Life</h2><div class="video-grid">${[['demo-alerts','Instant Alerts, Zero Noise','AI-powered, no false alarms.','0:32'],['demo-talk','Talk to Visitors From Anywhere','Two-way audio with clear sound quality','0:45'],['demo-night','Night Vision That Sees Everything','Color night vision up to 131 ft.','0:28']].map(([i,h,p,d])=>'<article>'+videoButton(i,h,d)+'<h4>'+h+'</h4><p>'+p+'</p></article>').join('')}</div></div></section><section class="section bg-pale"><div class="wrap"><div class="section-heading"><h2>What Other Customers Are Buying</h2><a href="#/category">View All Products</a></div><div class="product-grid">${['home-camera','doorbell','pet-camera'].map(id=>productCard(getProduct(id))).join('')}</div></div></section><section class="section gradient"><div class="wrap newsletter"><div><h2>Get <em class="green">10% Off</em> Your First Order</h2><p>Join 500,000+ homeowners who trust Amcrest. Get exclusive deals, setup tips, and new product alerts.</p><form id="newsletter-form" class="newsletter-form"><label class="sr-only" for="newsletter-email">Email address</label><input id="newsletter-email" type="email" placeholder="Enter your email address" required><button class="button">Subscribe</button></form><p id="newsletter-status" class="form-message" role="status"></p></div><img src="${asset('newsletter')}" alt="Amcrest smart home devices and alerts" loading="lazy"></div></section>`;}
function filters(withCategories=false){const group=(name,key,vals)=>'<div class="filter-group"><fieldset><legend>'+name+'</legend>'+vals.map(v=>'<label class="check"><input type="checkbox" data-filter="'+key+'" value="'+v+'" '+(filterState[key].has(v)?'checked':'')+'>'+v+'</label>').join('')+'</fieldset></div>';return '<aside class="filters" id="filters">'+(withCategories?'<h3>Category</h3><nav class="category-filters">'+['PoE Cameras','WiFi Cameras','Analog Cameras','Thermal Cameras','PTZ Cameras','Dual-Lens Cameras','Doorbells','Camera Systems (NVR)'].map(c=>'<a href="#/category?category='+encodeURIComponent(c)+'">'+c+'</a>').join('')+'</nav>':'')+'<h3>Filters</h3>'+group('RESOLUTION','res',['1080p','4MP','5MP','4K'])+group('TYPE','types',['Bullet','Turret','Dome','PTZ','Doorbell'])+'<div class="filter-group"><label class="label" for="price-max">PRICE</label><div class="price-range"><label class="sr-only" for="price-min">Minimum price</label><input id="price-min" type="range" min="29" max="699" value="'+(filterState.min||29)+'" data-price-min aria-label="Minimum price"><input id="price-max" type="range" min="29" max="699" value="'+filterState.max+'" data-price aria-label="Maximum price"></div><div class="range-row"><output id="price-min-output">$'+(filterState.min||29)+'</output><output id="price-output">$'+filterState.max+'</output></div></div>'+group('FEATURES','features',['AI Detection','Night Vision','Two-Way Audio','Spotlight'])+'<div class="filter-group"><fieldset><legend><span class="desktop-rating-prefix">CUSTOMER </span>RATING</legend><label class="check"><input type="radio" name="rating" value="5" data-rating '+(filterState.rating===5?'checked':'')+'><span class="stars">★★★★★</span> only</label><label class="check"><input type="radio" name="rating" value="4" data-rating '+(filterState.rating===4?'checked':'')+'><span class="stars">★★★★☆</span> & up</label></fieldset></div><button class="reset" data-action="clear-filters">Clear All</button><div class="filter-help"><h4>Need Help Choosing?</h4><button class="button" data-action="buying-guide">Read Buying Guide</button></div></aside>';}
function filtered(products){return products.filter(p=>(!filterState.res.size||filterState.res.has(p.resolution))&&(!filterState.types.size||filterState.types.has(p.type))&&[...filterState.features].every(f=>p.features.includes(f))&&p.price>=filterState.min&&p.price<=filterState.max&&p.rating>=filterState.rating);}
function empty(){return '<div class="empty-results"><h3>No products match these filters</h3><p>Try removing a filter to see more options.</p><button class="button secondary" data-action="clear-filters">Clear All</button></div>';}
function bundle(id){const p=getProduct(id);return '<p class="label" style="margin:30px 0 15px">RECOMMENDED BUNDLE</p><article class="bundle"><img loading="lazy" src="'+asset(p.image)+'" alt="'+p.name+'"><div class="copy"><h3>'+p.name+'</h3><p>'+p.description+'</p><strong class="price">'+money(p.price)+'</strong><span class="saving">Save <em>$'+p.saving+'</em> vs. buying separately</span><br><button class="button" data-add="'+p.id+'">Add to Cart</button></div></article>';}
function solutionsBody(){return SCENARIOS.map(s=>{const list=filtered(s.products.map(getProduct));return '<section class="scenario-section" id="need-'+s.id+'"><div class="scenario-banner" style="background-image:linear-gradient(90deg,#011835b8,#01183538),url('+asset(s.image)+')"><h2>'+s.name+'</h2><p>'+s.banner+'</p></div>'+(list.length?'<div class="product-grid">'+list.map(p=>productCard(p)).join('')+'</div>':empty())+bundle(s.bundle)+'</section>';}).join('');}
function solutions(){return '<main class="catalog-page"><div class="wrap catalog-layout">'+filters()+'<div class="catalog-main"><h1>Shop by <em>Need</em></h1><p class="subheading">Find your solution in a few clicks.</p><button class="mobile-filter-toggle" data-action="filters">'+icon('filter')+' Filters</button><nav class="scenario-tabs" aria-label="Shop by need">'+SCENARIOS.map((s,i)=>'<a href="#/solutions?need='+s.id+'" class="'+(i===0?'active':'')+'" data-need="'+s.id+'">'+s.name+'</a>').join('')+'</nav><div id="solution-sections">'+solutionsBody()+'</div></div></div></main>'+contact();}
function category(params){let cat=params.get('category')||'Security Cameras';return '<div class="breadcrumbs wrap" style="padding-top:20px">Home / Products / '+esc(cat)+'</div><section class="category-hero"><div class="wrap"><div><h1>See Everything.<br>Miss Nothing.</h1><p>Indoor, outdoor, wired or wireless — find the camera built for your space. Browse by spec, compare models, and choose the exact camera you need.</p></div><img src="'+asset('business-bundle')+'" alt="Amcrest security camera lineup"></div></section><main class="catalog-page"><div class="wrap catalog-layout">'+filters(true)+'<div class="catalog-main"><button class="mobile-filter-toggle" data-action="filters">'+icon('filter')+' Filters</button><div class="catalog-toolbar"><span id="result-count"></span><label>Sort by <select id="sort-products"><option value="featured">Featured</option><option value="price-low">Price: Low to High</option><option value="price-high">Price: High to Low</option><option value="rating">Customer Rating</option></select></label></div><div id="category-products" class="product-grid category-grid"></div><div id="compare-controls"></div><nav class="pagination" aria-label="Product pages"><button aria-label="Previous page" disabled>←</button><button class="active" aria-current="page">1</button><button aria-label="Next page" disabled>→</button></nav></div></div></main>'+buyingGuideSection()+contact();}
function categoryProducts(params){const cat=params.get('category')||'Security Cameras';let list=PRODUCTS.filter(p=>p.type!=='Bundle');if(cat==='Security Cameras'||cat.includes('Cameras'))list=list.filter(p=>p.category==='Security Cameras'||p.category==='Smart Home');if(cat.includes('PoE'))list=list.filter(p=>['Bullet','Turret','Dome','PTZ'].includes(p.type));if(cat.includes('WiFi'))list=list.filter(p=>p.id.includes('pet')||p.id.includes('vehicle-ptz')||p.type==='Doorbell');if(cat.includes('GPS'))list=list.filter(p=>p.type==='GPS');if(cat.includes('PTZ'))list=list.filter(p=>p.type==='PTZ');if(cat.includes('Doorbell'))list=list.filter(p=>p.type==='Doorbell');if(cat.includes('Recorders')||cat.includes('Systems')||cat.includes('NVR'))list=list.filter(p=>p.type==='NVR');if(cat.includes('Accessory')||cat.includes('Accessories')||cat.includes('Mounts')||cat.includes('Cables')||cat.includes('Drives'))list=list.filter(p=>p.type==='Accessory');if(['Analog Cameras','Thermal Cameras','Dual-Lens Cameras','Baby Monitors','Webcams','Microphones','Smart Baby Monitor','USB Webcams','NAS Storage','DVR Recorders'].includes(cat))list=[];const q=params.get('q');if(q)list=list.filter(p=>[p.name,p.category,p.sku,...p.features].join(' ').toLowerCase().includes(q.toLowerCase()));return filtered(list);}
function refreshCategory(){let list=categoryProducts(readRoute().params);const sort=document.querySelector('#sort-products')?.value;if(sort==='price-low')list.sort((a,b)=>a.price-b.price);if(sort==='price-high')list.sort((a,b)=>b.price-a.price);if(sort==='rating')list.sort((a,b)=>b.rating-a.rating);document.querySelector('#result-count').textContent=(readRoute().params.get('q')?'Results for “'+readRoute().params.get('q')+'” · ':'')+'Showing '+list.length+' products';document.querySelector('#category-products').innerHTML=list.length?list.map(p=>productCard(p,{category:true})).join(''):empty();document.querySelector('#compare-controls').innerHTML=compare.length?'<p style="text-align:right;margin-top:24px"><button class="button secondary" data-action="show-compare">Compare ('+compare.length+')</button> <button class="blue-link" data-action="clear-compare">Clear</button></p>':'';}
function buyingGuideSection(){return '<section class="section gradient"><div class="wrap buying-guide"><div><h2>Not Sure Which Camera Is Right for You?</h2><p>Our buying guide breaks down everything in plain language — no jargon, no confusion.</p><ul><li>Indoor vs. outdoor: which do you actually need?</li><li>WiFi vs. PoE: what’s the difference?</li><li>Resolution explained: 1080p, 4MP, 5MP, 4K</li><li>AI detection, night vision, and two-way audio</li></ul><button class="button" data-action="buying-guide">Read the Buying Guide</button></div><img src="'+asset('business-bundle')+'" alt="Amcrest camera types"></div></section>';}
function product(params){const p=getProduct(params.get('id'))||getProduct('camera');const flagship=p.id==='camera';selectedPhoto=flagship?'camera-front':p.image;const thumbs=flagship?['camera-front','camera-side','camera-back','camera-angle','camera-night']:[p.image];return '<main><div class="wrap product-top"><div class="product-gallery"><img class="main-product-image" id="main-product-image" src="'+asset(selectedPhoto)+'" alt="'+esc(p.name)+'"><div class="thumbnails">'+thumbs.map((im,i)=>'<button data-photo="'+im+'" class="'+(i===0?'selected':'')+'" aria-label="Product image '+(i+1)+'" aria-pressed="'+(i===0)+'"><img src="'+asset(im)+'" alt=""></button>').join('')+'</div><span class="label">COLOR</span><div class="color-options"><button data-color="White" class="selected" aria-pressed="true">White</button><button data-color="Black" aria-pressed="false">Black</button></div></div><div class="product-description"><span class="label">'+(p.type==='GPS'?'GPS TRACKER':p.type==='Accessory'?'ACCESSORY':p.type==='Bundle'?'SECURITY SYSTEM':p.type==='NVR'?'SYSTEMS & RECORDERS':'OUTDOOR SECURITY CAMERA')+'</span><h1>'+esc(p.name)+'</h1><div class="rating"><span class="stars">'+('★'.repeat(p.rating)+'☆'.repeat(5-p.rating))+'</span><span>'+p.reviews.toLocaleString()+' Reviews</span></div><div class="sku">'+esc(p.id==='camera'?p.sku:'')+' · <span id="selected-color">White</span></div><div class="product-price"><strong class="price">'+money(p.price)+'</strong>'+(p.oldPrice?'<span class="old-price">'+money(p.oldPrice)+'</span><span class="tag-blue">SAVE 18%</span>':'')+'</div><p class="availability">Free 2-day shipping · In stock — ships today</p><p class="description">'+(flagship?'Capture ultra-clear 4K footage day and night. Built-in AI tells the difference between people, vehicles, and animals — so you only get alerts that matter.':p.description||SCENARIOS.find(s=>s.id===p.scenario)?.banner||p.name)+'</p><ul class="checks">'+(flagship?['4K Ultra HD (3840 × 2160) at 20fps','AI-powered person & vehicle detection','Color night vision up to 98 ft','IP67 weatherproof — rain, snow, dust','PoE (one cable for power + data)','Works with Amcrest Smart Home app']:[(p.resolution?p.resolution+' resolution':p.name),...p.features]).map(s=>'<li>'+s+'</li>').join('')+'</ul><div class="purchase-row"><div class="quantity"><button data-action="product-minus" aria-label="Decrease quantity">−</button><input id="product-quantity" type="number" min="1" max="99" value="1" aria-label="Product quantity"><button data-action="product-plus" aria-label="Increase quantity">+</button></div><button class="button" data-product-add="'+p.id+'">Add to Cart</button></div></div></div>'+featureBand('product',p)+'<section class="section gradient"><div class="wrap"><div class="detail-tabs" role="tablist" aria-label="Product information">'+['Details','Specifications','Reviews ('+p.reviews.toLocaleString()+')','FAQ'].map((s,i)=>'<button role="tab" id="tab-'+i+'" aria-controls="product-panel" aria-selected="'+(i===0)+'" tabindex="'+(i===0?0:-1)+'" data-detail-tab="'+s+'" class="'+(i===0?'active':'')+'">'+s+'</button>').join('')+'</div><div id="product-panel" role="tabpanel" aria-labelledby="tab-0">'+productDetails(p)+'</div></div></section><section class="section"><div class="wrap box-grid"><div><h2>What’s in the Box</h2><p>Everything you need to get started — no extra purchases required.</p><ul class="checks"><li>'+esc(p.short||p.name)+' × 1</li>'+ (flagship?'<li>Waterproof connector cap</li><li>Mounting bracket & screws</li><li>Hex wrench for tilt adjustment</li><li>Quick start guide</li><li>Reset pin</li>':'')+'</ul></div>'+videoButton('box','What’s in the Box','0:32')+'</div></section><section class="section bg-pale"><div class="wrap"><h2>Complete Your Setup</h2><p>Everything you need to install, connect, and protect your new camera.</p><div class="accessory-grid">'+['junction','switch','cable','sd'].map(id=>productCard(getProduct(id))).join('')+'</div></div></section><section class="section"><div class="wrap"><h2>You Might Also Like</h2><p>Customers who bought this camera also considered these options.</p><div class="product-grid">'+['home-camera','doorbell','pet-camera'].map(id=>productCard(getProduct(id))).join('')+'</div></div></section>'+buyingGuideSection()+'</main>';}
function productDetails(p){if(p.id!=='camera')return '<article class="detail-block"><div><h3>'+esc(p.name)+'</h3><p>'+esc(p.description||SCENARIOS.find(s=>s.id===p.scenario)?.banner||p.name)+'</p><ul class="checks">'+[p.resolution,p.type,...p.features].filter(Boolean).map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul></div><img class="detail-image" src="'+asset(p.image)+'" alt="'+esc(p.name)+'"></article>';return `<article class="detail-block"><div><h3>Superior 4K 8-Megapixel at 25 FPS</h3><p>Featuring the latest progressive scanning image sensor and Chipset, the Amcrest UltraHD camera soaks in the entire scene, dynamically painting all the vivid colors and rich imagery, pixel by pixel, onto your computer screen or smartphone in full 2560x1440 resolution. Offers 4K resolution @ 25fps when WDR is Off, 4K @ 20fps when WDR is on. No need to strain your eyes, lean in close, or play the guessing game when you have this level of detail.</p></div><img class="detail-image" src="${asset('people-count')}" alt="People counting example" loading="lazy"></article><article class="detail-block"><div><h3>Advanced Zone Detection</h3><p>Create distinct motion detection zones to completely customize control over what you’re monitoring. Each zone includes its own sensitivity and threshold meters so you can fine-tune it exactly to your liking. Let the Amcrest camera hold its focus so you don’t have to lose yours.</p></div><img class="detail-image" src="${asset('zone')}" alt="Motion detection zones" loading="lazy"></article><article class="detail-block"><div><h3>Intelligent Timeline Playback</h3><p>Your stored recordings and pictures are precious, and having that data at hand is the whole point of using a security camera. The camera’s intuitive searchable timeline helps you identify, track down, play back and export what you want, when you want it.</p></div><img class="detail-image" src="${asset('timeline')}" alt="Recorded footage timeline" loading="lazy"></article><div class="more-features"><h2>More Features You’ll Love</h2><div class="three-grid">${[['weather','IP67 Weatherproof','Handles rain, snow, dust, and temperatures from −22°F to 140°F.'],['wide','108° Wide Angle','Cover your entire front yard, driveway, or parking lot without blind spots.'],['app','Amcrest Smart Home App','Watch live, get alerts, and play back footage from anywhere on your phone.']].map(([im,h,t])=>'<article><img src="'+asset(im)+'" alt="'+h+'" loading="lazy"><h3>'+h+'</h3><p>'+t+'</p></article>').join('')}</div></div>`;}
function cloud(){return `<main><section class="cloud-hero"><div class="wrap"><div class="copy"><h1>Your Footage,<br>Always Safe</h1><p>Even if someone steals your camera, your footage is already in the cloud. Access recordings from anywhere, anytime — on your phone, tablet, or computer.</p><div class="actions"><a class="button" href="#plans" data-scroll="plans">See Plans & Pricing</a><button class="button" data-plan="Standard">Start Free Trial</button></div><div class="cloud-stats"><div><strong>500K+</strong><small>CAMERAS CONNECTED</small></div><div><strong>99.9%</strong><small>UPTIME SLA</small></div><div><strong>256-bit</strong><small>AES ENCRYPTION</small></div></div></div></div></section>${featureBand('cloud')}<section class="section gradient"><div class="wrap"><h2>Set Up in 3 Minutes</h2><p>No technician, no NVR box, no complicated wiring. Just your camera and the app.</p><div class="three-grid">${[['cloud-hero','Connect Your Camera','Open the Amcrest Smart Home app and add your camera. It takes under 2 minutes.'],['cloud-second','Choose a Cloud Plan','Pick the storage window that fits your needs. Start with a free 1-year trial — no credit card required.'],['cloud-third','Watch & Playback','Your footage is automatically saved. Scrub the timeline, play clips, or download them to your phone.']].map(([im,h,t],i)=>'<article class="setup-step center"><div class="step-number">'+(i+1)+'</div><img src="'+asset(im)+'" alt="'+h+'" loading="lazy"><h3>'+h+'</h3><p>'+t+'</p></article>').join('')}</div></div></section><section class="section bg-pale" id="plans"><div class="wrap"><h2>Per-Camera Pricing</h2><p>No contracts. Cancel anytime. Every plan includes AI-powered detection and unlimited event recordings.</p><div class="billing-switch"><button data-billing="monthly" class="active" aria-pressed="true">Monthly</button><button data-billing="annual" aria-pressed="false">Annual (Save 20%)</button></div><div class="free-plan"><div><h3>Free for 1 Year — No Credit Card Needed</h3><p>Every new Amcrest camera comes with a free 1-year cloud plan. 3-day motion storage included at no cost.</p></div><button class="button" data-plan="Free">Activate Free Plan</button></div><div class="plans" id="plan-cards">${planCards()}</div></div></section><section class="section gradient"><div class="wrap"><h2>Cloud vs. Local Storage</h2><p>Cloud and local storage work great together — but here’s how they compare on their own.</p><div class="comparison"><table><thead><tr><th>Feature</th><th>Amcrest Cloud</th><th>MicroSD Card</th><th>NVR System</th></tr></thead><tbody>${[['Theft-proof recording','✓','—','—'],['Access from anywhere','✓','—','✓ (with port forwarding)'],['AI detection filtering','✓','—','Camera-dependent'],['No hardware required','✓','SD card needed','NVR + HDD needed'],['Continuous recording','Motion only','✓','✓'],['Monthly cost','From $1.99/mo','$0 (one-time purchase)','$0 (one-time purchase)'],['Max storage','Unlimited events','Up to 256GB','Up to 16TB'],['Setup time','3 minutes','5 minutes','30+ minutes']].map(row=>'<tr>'+row.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')}</tbody></table></div></div></section><section class="section cloud-bottom"><div class="wrap"><h2>Start Protecting Your Footage Today</h2><p>Free for your first year. No credit card required.<br>Set up in under 3 minutes.</p><div class="actions"><button class="button" data-plan="Free">Activate Free Plan</button><button class="button" data-scroll="plans">Compare Plans</button></div></div></section></main>`;}
function planCards(){return PLANS.map(p=>'<article class="plan '+(p.popular?'popular':'')+'">'+(p.popular?'<span class="popular-label">MOST POPULAR</span>':'')+'<h3>'+p.name+'</h3><span class="days">'+p.days+'-Day</span><small>rolling storage</small><div class="plan-price">'+money(p.price*(billing==='annual'?.8:1))+'<small> / mo</small></div><small>per camera'+(billing==='annual'?' · billed annually':'')+'</small><ul><li>✓ Motion-triggered recording</li><li>✓ '+(p.limited?'12-second':'Unlimited')+' clip length</li><li>✓ Push notifications</li><li>✓ Mobile & web playback</li><li>'+(p.limited?'—':'✓')+' AI person & vehicle detection</li><li>'+(p.limited?'—':'✓')+' No cooldown between events</li></ul><button class="button" data-plan="'+p.name+'">Start Free Trial</button></article>').join('');}
function faq(items=FAQ){return '<div class="faq">'+items.map(([q,a],i)=>'<details '+(i===1?'open':'')+'><summary>'+esc(q)+'</summary><p>'+esc(a)+'</p></details>').join('')+'</div>';}
function support(){const topics=[['Getting Started','Unboxing, first-time setup, connecting to WiFi or PoE, and adding cameras to the app.','phone'],['App & Software','Amcrest Smart Home app, Amcrest View Pro, desktop software, and firmware updates.','chip'],['Cloud Storage','Cloud plans, activating free storage, managing recordings, and billing questions.','cloud'],['Troubleshooting','Camera offline, no video, connection issues, motion detection not working, and more.','chip'],['Installation','Mounting guides, PoE wiring, NVR setup, outdoor weatherproofing, and cable management.','cable'],['Account & Security','Reset password, two-factor auth, sharing access, privacy settings, and data protection.','shield']];return `<main><section class="support-hero"><div class="wrap"><h1>How Can We Help?</h1><form id="support-search" class="support-search"><label class="sr-only" for="support-query">Search support</label><input id="support-query" type="search" placeholder="Search for setup guides, troubleshooting, FAQs…"><button aria-label="Search support">${icon('search')}</button></form><div class="popular-search">Popular: ${['camera setup','reset password','cloud plans','night vision','firmware update'].map(s=>'<button data-support-search="'+s+'">'+s+'</button>').join('')}</div></div></section><section class="section"><div class="wrap"><h2>What Do You Need Help With?</h2><div class="help-grid">${topics.map(([h,p,i])=>'<article class="help-card"><span class="small-circle" aria-hidden="true">'+icon(i)+'</span><h3>'+h+'</h3><p>'+p+'</p><button class="button" data-help-topic="'+h+'">Get Help</button></article>').join('')}</div></div></section><section class="section gradient"><div class="wrap"><h2>Warranty & Returns</h2><article class="warranty-row"><img src="${asset('warranty')}" alt="Warranty protection" loading="lazy"><div><h3><em>1-Year</em> Limited Warranty</h3><p>All Amcrest products come with a 1-year manufacturer’s warranty covering defects in materials and workmanship.</p><ul class="checks"><li>Coverage begins from date of purchase</li><li>Covers all cameras, NVRs, and accessories</li><li>Free replacement for manufacturing defects</li></ul><button class="button" data-claim="Warranty">Submit Warranty Claim</button></div></article><article class="warranty-row"><img src="${asset('return')}" alt="Return your camera" loading="lazy"><div><h3><em>30-Day</em> Return Policy</h3><p>Not satisfied? Return your product within 30 days of purchase for a full refund, no questions asked.</p><ul class="checks"><li>Product must be in original packaging</li><li>Free return shipping label provided</li><li>Refund processed within 5 business days</li></ul><button class="button" data-claim="Return">Submit Warranty Claim</button></div></article></div></section><section class="section"><div class="wrap"><h2>General Support Questions</h2><div id="support-faq">${faq()}</div></div></section>${contact()}</main>`;}
function account(){const orders=[['camera-front','4K PoE Turret Camera × 2','Apr 28, 2026','SHIPPED'],['nvr','8-Ch 4K PoE NVR','Apr 15, 2026','DELIVERED'],['cable','Cat5e Cable 100ft × 3','Mar 30, 2026','DELIVERED']];return `<main><section class="account-main"><div class="wrap account-layout"><aside class="account-sidebar"><h2>${esc(accountName)} Xue</h2><p>celine.xue@email.com</p><nav aria-label="Account"><button class="active" data-scroll="account-overview">Overview</button><button data-scroll="recent-orders">Orders &nbsp; ③</button><button data-scroll="my-cameras">My Cameras</button><a href="#/cloud">Cloud Plans</a><button data-account-action="Addresses">Addresses</button><button data-account-action="Account Settings">Account Settings</button><button data-account-action="Sign Out">Sign Out</button></nav></aside><div class="account-content" id="account-overview"><h1>Welcome back, ${esc(accountName)}</h1><p>Here’s a snapshot of your account.</p><div class="account-stats"><div class="stat"><span>ACTIVE CAMERAS</span><strong>4</strong><small>3 online · 1 offline</small></div><div class="stat"><span>CLOUD PLANS</span><strong>3</strong><small>7-Day Standard</small></div><div class="stat"><span>OPEN ORDERS</span><strong>1</strong><small>Shipped — in transit</small></div></div><div id="recent-orders"><div class="section-heading"><h3>Recent Orders</h3><button class="blue-link" data-account-action="Orders">View All Orders</button></div><table class="orders-table"><thead><tr><th>ORDER</th><th>DATE</th><th>STATUS</th></tr></thead><tbody>${orders.map(([im,n,d,s])=>'<tr><td><button class="order-product" data-order="'+n+'"><img src="'+asset(im)+'" alt="">'+n+'</button></td><td>'+d+'</td><td><span class="status">'+s+'</span></td></tr>').join('')}</tbody></table></div></div></div></section><section class="section bg-pale" id="my-cameras"><div class="wrap"><div class="content-offset"><div class="section-heading"><h3>My Cameras</h3><button class="blue-link" data-account-action="My Cameras">Manage Cameras</button></div><div class="camera-grid">${[['Front Porch','IP8M-T2779EW-AI','porch'],['Backyard','IP8M-2496EW-V3','backyard'],['Living Room','ASH41-W','living-room'],['Garage','IP8M-T2779EW-AI','garage']].map(([h,s,im])=>'<article>'+videoButton(im,h)+'<h3>'+h+'</h3><p>'+s+'</p></article>').join('')}</div></div></div></section></main>`;}
function mobileNavigation(){return `<div class="mobile-nav" id="mobile-nav" role="dialog" aria-modal="true" aria-label="Mobile navigation" hidden><div class="mobile-nav-header"><a class="brand" href="#/home">${logo}</a><button class="close-button" data-action="close-mobile" aria-label="Close menu">×</button></div><form class="search-row" id="mobile-search-form"><label class="sr-only" for="mobile-search">Search products, guides, FAQs</label><input id="mobile-search" placeholder="Search products, guides, FAQs…" type="search"><button aria-label="Search">${icon('search')}</button></form><details open><summary>Products</summary>${['Security Cameras','Systems & Recorders','Smart Home','GPS Trackers','Baby Monitors','Webcams & Audio','Accessories & Infrastructure','Certified Refurbished'].map(c=>'<a href="#/category?category='+encodeURIComponent(c)+'">'+c+'</a>').join('')}<a href="#/category">View All Products ›</a><a href="#/solutions">Shop by Need</a></details><details><summary>Services</summary><a href="#/cloud">Cloud</a><a href="#/cloud">GPS Tracking Plans</a><a href="#/support">Mobile Apps</a></details><details><summary>Support</summary><a href="#/support">Help Center</a><a href="#/support">Setup Videos</a><a href="#/support">Contact Us</a></details><details><summary>My Account</summary><a href="#/account">Overview</a><a href="#/account?section=recent-orders">Orders (3)</a><a href="#/account?section=my-cameras">My Cameras</a><a href="#/cloud">Cloud Plans</a><button data-account-action="Addresses">Addresses</button><button data-account-action="Account Settings">Account Settings</button><button data-account-action="Sign Out">Sign Out</button></details><button data-cart-open>Cart <span data-cart-count>${cartCount()}</span> ›</button></div>`;}
function render(){const {path,params}=readRoute();const key=['home','solutions','category','product','cloud','support','account'].includes(path)?path:'home';currentRoute=key;navPanel='';mobileMenu=false;selectedColor='White';productQty=1;detailTab='Details';billing='monthly';app.className=key+'-page';app.innerHTML=header(key)+'<div id="main" tabindex="-1">'+({home,solutions,category:()=>category(params),product:()=>product(params),cloud,support,account}[key]())+'</div>'+footer()+mobileNavigation();document.title='Amcrest | '+({home:'See Everything. Protect Everyone.',solutions:'Shop by Need',category:'Security Cameras',product:'Product Details',cloud:'Cloud Service',support:'Help Center',account:'My Account'}[key]);if(key==='category')refreshCategory();if(key==='solutions'&&params.get('need')){const need=params.get('need');requestAnimationFrame(()=>{document.querySelector('#need-'+CSS.escape(need))?.scrollIntoView({behavior:'instant'});setActiveNeed(need);});}else if(key==='account'&&params.get('section')){requestAnimationFrame(()=>document.querySelector('#'+CSS.escape(params.get('section')))?.scrollIntoView({behavior:'instant'}));}else window.scrollTo({top:0,behavior:'instant'});saveCart();}
function setActiveNeed(id){document.querySelectorAll('[data-need]').forEach(a=>a.classList.toggle('active',a.dataset.need===id));}
function refreshFiltered(){if(currentRoute==='solutions')document.querySelector('#solution-sections').innerHTML=solutionsBody();if(currentRoute==='category')refreshCategory();announce('Product filters updated');}
function toggleNav(which){navPanel=navPanel===which?'':which;document.querySelector('#products-panel').hidden=navPanel!=='products';document.querySelector('#search-panel').hidden=navPanel!=='search';document.querySelector('[data-action="products-menu"]').setAttribute('aria-expanded',String(navPanel==='products'));document.querySelector('[data-action="search-menu"]').setAttribute('aria-expanded',String(navPanel==='search'));if(navPanel==='search')document.querySelector('#product-search').focus();}
function closeNav(){navPanel='';document.querySelectorAll('.nav-panel').forEach(p=>p.hidden=true);document.querySelectorAll('.header [aria-expanded]').forEach(p=>p.setAttribute('aria-expanded','false'));}
function openContent(title,body){if(contentDialog.open)contentDialog.close();contentDialog.innerHTML='<div class="dialog-header"><h2 id="dialog-title">'+esc(title)+'</h2><button class="close-button" data-close-content aria-label="Close dialog">×</button></div>'+body;contentDialog.showModal();document.body.classList.add('modal-open');}
function renderCart(){cartDialog.innerHTML='<div class="cart-header"><h2 id="cart-title">Cart ('+cartCount()+')</h2><button class="close-button" data-close-cart aria-label="Close cart">×</button></div>'+(cart.length?cart.map((item,index)=>{const p=getProduct(item.id);return '<article class="cart-item"><img src="'+asset(p.image)+'" alt="'+esc(p.name)+'"><div><h3>'+esc(p.short||p.name)+'</h3><div class="variant">'+esc(item.color)+'</div><div class="quantity"><button data-cart-delta="-1" data-index="'+index+'" aria-label="Decrease '+esc(p.short||p.name)+' quantity">−</button><input type="number" min="1" max="99" value="'+item.qty+'" data-cart-quantity="'+index+'" aria-label="Quantity for '+esc(p.name)+'"><button data-cart-delta="1" data-index="'+index+'" aria-label="Increase '+esc(p.short||p.name)+' quantity">+</button></div><button class="remove" data-remove="'+index+'">Remove</button></div><span class="cart-price">'+money(p.price*item.qty)+'</span></article>';}).join('')+'<div class="cart-summary"><span>Subtotal</span><span>'+money(cartTotal())+'</span></div><button class="button" data-action="checkout">Checkout</button><button class="button secondary" data-action="view-cart">View Full Cart</button>':'<div class="cart-empty"><h3>Your cart is empty</h3><p>Find the right camera for your space.</p><button class="button" data-action="continue-shopping">Continue Shopping</button></div>');}
function openCart(){closeNav();if(mobileMenu)closeMobile();renderCart();if(!cartDialog.open)cartDialog.showModal();document.body.classList.add('modal-open');}
function addCart(id,qty=1,color='White'){if(!getProduct(id))return;const item=cart.find(i=>i.id===id&&i.color===color);if(item)item.qty=Math.min(99,item.qty+qty);else cart.push({id,qty:Math.min(99,qty),color});saveCart();announce(getProduct(id).name+' added to cart');openCart();}
function closeMobile(){mobileMenu=false;document.querySelector('#mobile-nav').hidden=true;document.body.classList.remove('modal-open');document.querySelector('[data-action="mobile-menu"]')?.focus();}
function searchProducts(q,mobile=false){const term=q.trim().toLowerCase();const results=PRODUCTS.filter(p=>p.type!=='Bundle'&&[p.name,p.category,p.sku,...p.features].join(' ').toLowerCase().includes(term));if(mobile){closeMobile();location.hash=link('category?category=All%20Products&q='+encodeURIComponent(q));return;}document.querySelector('#search-results').innerHTML=term?(results.length?results.slice(0,8).map(p=>'<a href="#/product?id='+(p.detail||p.id)+'"><img src="'+asset(p.image)+'" alt=""><span>'+esc(p.name)+'<br><strong>'+money(p.price)+'</strong></span></a>').join(''):'<p class="form-message">No results. Try camera, doorbell or GPS.</p>'):'';}
function buyingGuide(){openContent('Buying Guide','<p>Choose what you want to protect, then compare the setup that fits your space.</p><ul class="checks"><li><strong>PoE:</strong> one Ethernet cable carries power and data.</li><li><strong>WiFi:</strong> a wireless network connection, with a separate power source.</li><li><strong>Resolution:</strong> compare 1080p, 4MP, 5MP and 4K.</li><li><strong>Features:</strong> consider night vision, AI detection and two-way audio.</li></ul><div class="actions">'+SCENARIOS.map(s=>primary(s.name,'solutions?need='+s.id,'secondary')).join(' ')+'</div>');}
function showCheckout(){cartDialog.close();openContent('Checkout','<p>Your selected items are ready for the checkout preview.</p>'+cart.map(i=>'<div class="checkout-line"><span>'+esc(getProduct(i.id).short||getProduct(i.id).name)+' × '+i.qty+'</span><strong>'+money(getProduct(i.id).price*i.qty)+'</strong></div>').join('')+'<div class="checkout-line"><strong>Subtotal</strong><strong>'+money(cartTotal())+'</strong></div><p class="form-message">This course redesign stops before payment. No order will be placed.</p><button class="button secondary" data-action="back-cart">Back to Cart</button>');}
function accountAction(action){if(mobileMenu)closeMobile();if(action==='Sign Out'){accountSignedOut=true;openContent('Signed out','<p>You have signed out of the demo account.</p><button class="button" data-action="restore-account">Return to Demo Account</button>');return;}if(action==='Orders'){document.querySelector('#recent-orders')?.scrollIntoView();return;}if(action==='My Cameras'){document.querySelector('#my-cameras')?.scrollIntoView();return;}if(action==='Account Settings'){openContent('Account Settings','<form id="account-settings"><label for="account-name">First name</label><input id="account-name" required maxlength="40" value="'+esc(accountName)+'"><button class="button">Save Changes</button><p id="settings-message" class="form-message" role="status"></p></form>');return;}openContent('Addresses','<form id="address-form"><label for="address-name">Name</label><input id="address-name" required><label for="address-line">Address</label><input id="address-line" required><label for="address-city">City</label><input id="address-city" required><button class="button">Save Address</button><p id="address-message" class="form-message" role="status"></p></form>');}
app.addEventListener('click',event=>{
 const el=event.target.closest('button,a');if(!el)return;
 if(el.tagName==='A'&&el.hash.startsWith('#/')){if(mobileMenu)closeMobile();closeNav();}
 if(el.matches('[data-cart-open]'))return openCart();
 if(el.dataset.add)return addCart(el.dataset.add);
 if(el.dataset.productAdd)return addCart(el.dataset.productAdd,productQty,selectedColor);
 if(el.dataset.photo){selectedPhoto=el.dataset.photo;document.querySelector('#main-product-image').src=asset(selectedPhoto);document.querySelectorAll('[data-photo]').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',String(b===el));});return;}
 if(el.dataset.color){selectedColor=el.dataset.color;document.querySelector('#selected-color').textContent=selectedColor;document.querySelectorAll('[data-color]').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',String(b===el));});return;}
 if(el.dataset.need){event.preventDefault();const id=el.dataset.need;history.replaceState(null,'',link('solutions?need='+id));document.querySelector('#need-'+id).scrollIntoView();setActiveNeed(id);return;}
 if(el.dataset.scroll){event.preventDefault();document.querySelector('#'+CSS.escape(el.dataset.scroll))?.scrollIntoView();return;}
 if(el.dataset.detailTab){detailTab=el.dataset.detailTab;document.querySelectorAll('[data-detail-tab]').forEach((b,i)=>{const active=b===el;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;if(active)document.querySelector('#product-panel').setAttribute('aria-labelledby',b.id);});const p=getProduct(readRoute().params.get('id'))||getProduct('camera');document.querySelector('#product-panel').innerHTML=detailTab==='Details'?productDetails(p):detailTab==='Specifications'?'<div class="comparison"><table><tbody>'+[['Model',p.sku||p.name],['Resolution',p.resolution||'See product description'],['Type',p.type],['Color',selectedColor],['Features',p.features.join(', ')||'See product description']].map(r=>'<tr><th>'+r[0]+'</th><td>'+esc(r[1])+'</td></tr>').join('')+'</tbody></table></div>':detailTab==='FAQ'?faq(): '<h3>Customer Reviews</h3><p><span class="stars">'+('★'.repeat(p.rating))+'</span> &nbsp; '+p.reviews.toLocaleString()+' reviews</p><p>Individual review text was not included in the design prototype.</p>';return;}
 if(el.dataset.billing){billing=el.dataset.billing;document.querySelectorAll('[data-billing]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',String(b===el));});document.querySelector('#plan-cards').innerHTML=planCards();return;}
 if(el.dataset.plan){openContent(el.dataset.plan+' Cloud Plan','<p>'+esc(el.dataset.plan)+' selected'+(el.dataset.plan==='Free'?'': ' · '+billing+' billing')+'.</p><p class="form-message">This is a plan-selection preview. No subscription is created.</p><button class="button" data-close-content>Continue Exploring</button>');return;}
 if(el.dataset.preview){openContent(el.dataset.title,'<img class="preview-image" src="'+asset(el.dataset.preview)+'" alt="'+esc(el.dataset.title)+'"><p class="form-message">Design preview. A video source was not included in the Figma materials.</p>');return;}
 if(el.dataset.contact){openContent(el.dataset.contact,'<p>Contact preview for the independent course redesign.</p><p class="form-message">No message or call is sent from this demo.</p><button class="button" data-close-content>Close</button>');return;}
 if(el.dataset.claim){openContent(el.dataset.claim+' Request','<form id="claim-form"><label for="claim-order">Order number</label><input id="claim-order" required><label for="claim-model">Camera model</label><input id="claim-model" required><label for="claim-details">Details</label><textarea id="claim-details" required></textarea><button class="button">Preview Request</button><p id="claim-message" class="form-message" role="status"></p></form>');return;}
 if(el.dataset.social){openContent(el.dataset.social,'<p>Social-link preview. No brand account URL was included in the course design.</p>');return;}
 if(el.dataset.policy){openContent(el.dataset.policy,'<p>This section is a navigation preview in the course redesign. The full '+esc(el.dataset.policy.toLowerCase())+' content was not provided in the design.</p>');return;}
 if(el.dataset.search){toggleNav('search');document.querySelector('#product-search').value=el.dataset.search;searchProducts(el.dataset.search);return;}
 if(el.dataset.supportSearch){supportSearch(el.dataset.supportSearch);return;}
 if(el.dataset.helpTopic){if(el.dataset.helpTopic==='Cloud Storage'){location.hash=link('cloud');return;}openContent(el.dataset.helpTopic,faq());return;}
 if(el.dataset.accountAction)return accountAction(el.dataset.accountAction);
 if(el.dataset.order){openContent('Order Details','<p>'+esc(el.dataset.order)+'</p><p class="form-message">Sample order from the Figma account design.</p>');return;}
 if(el.dataset.compare){const id=el.dataset.compare;if(compare.includes(id))compare=compare.filter(s=>s!==id);else if(compare.length<3)compare.push(id);else return announce('Compare up to 3 products');refreshCategory();return;}
 const action=el.dataset.action;
 if(action==='products-menu')toggleNav('products');if(action==='search-menu')toggleNav('search');if(action==='close-menu')closeNav();
 if(action==='mobile-menu'){mobileMenu=true;document.querySelector('#mobile-nav').hidden=false;document.body.classList.add('modal-open');document.querySelector('[data-action="close-mobile"]').focus();}
 if(action==='close-mobile')closeMobile();
 if(action==='filters'){const box=document.querySelector('#filters');box.classList.toggle('mobile-open');el.setAttribute('aria-expanded',String(box.classList.contains('mobile-open')));}
 if(action==='clear-filters'){filterState.res.clear();filterState.types.clear();filterState.features.clear();filterState.min=0;filterState.max=699;filterState.rating=0;document.querySelectorAll('[data-filter],[data-rating]').forEach(i=>i.checked=false);const range=document.querySelector('[data-price]');if(range)range.value=699;const minimum=document.querySelector('[data-price-min]');if(minimum)minimum.value=29;const minOutput=document.querySelector('#price-min-output');if(minOutput)minOutput.textContent='$29';const output=document.querySelector('#price-output');if(output)output.textContent='$699';refreshFiltered();}
 if(action==='product-plus'||action==='product-minus'){productQty=Math.max(1,Math.min(99,productQty+(action==='product-plus'?1:-1)));document.querySelector('#product-quantity').value=productQty;}
 if(action==='buying-guide')buyingGuide();
 if(action==='show-compare'){openContent('Compare Products','<div class="compare-table"><table><thead><tr><th></th>'+compare.map(id=>'<th>'+esc(getProduct(id).name)+'</th>').join('')+'</tr></thead><tbody>'+[['Product',p=>'<img src="'+asset(p.image)+'" alt="'+esc(p.name)+'">'],['Price',p=>money(p.price)],['Resolution',p=>p.resolution||'—'],['Type',p=>p.type],['Features',p=>p.features.join(', ')||'—']].map(([title,value])=>'<tr><th>'+title+'</th>'+compare.map(id=>'<td>'+value(getProduct(id))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>');}
 if(action==='clear-compare'){compare=[];refreshCategory();}
});
function supportSearch(q){document.querySelector('#support-query').value=q;const matches=FAQ.filter(pair=>pair.join(' ').toLowerCase().includes(q.toLowerCase()));document.querySelector('#support-faq').innerHTML=matches.length?faq(matches):'<p>No exact matches. Browse the general support questions below.</p>'+faq();document.querySelector('#support-faq').scrollIntoView();announce('Support results updated');}
app.addEventListener('input',e=>{if(e.target.id==='product-search')searchProducts(e.target.value);if(e.target.matches('[data-price-min]')){filterState.min=Math.min(filterState.max,+e.target.value);e.target.value=filterState.min;document.querySelector('#price-min-output').textContent='$'+filterState.min;refreshFiltered();}if(e.target.matches('[data-price]')){filterState.max=Math.max(filterState.min||29,+e.target.value);e.target.value=filterState.max;document.querySelector('#price-output').textContent='$'+filterState.max;refreshFiltered();}});
app.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter){if(el.checked)filterState[el.dataset.filter].add(el.value);else filterState[el.dataset.filter].delete(el.value);refreshFiltered();}if(el.matches('[data-rating]')){filterState.rating=+el.value;refreshFiltered();}if(el.id==='sort-products')refreshCategory();if(el.id==='product-quantity'){productQty=Math.max(1,Math.min(99,Math.round(Number(el.value)||1)));el.value=productQty;}});
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='search-form')searchProducts(document.querySelector('#product-search').value);if(e.target.id==='mobile-search-form')searchProducts(document.querySelector('#mobile-search').value,true);if(e.target.id==='support-search')supportSearch(document.querySelector('#support-query').value);if(e.target.id==='newsletter-form'){document.querySelector('#newsletter-status').textContent='Subscription preview complete. No email has been submitted.';announce('Subscription preview complete');}});
cartDialog.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.matches('[data-close-cart]'))cartDialog.close();if(el.dataset.remove!==undefined){cart.splice(+el.dataset.remove,1);saveCart();renderCart();cartDialog.querySelector('[data-remove="'+Math.min(+el.dataset.remove,cart.length-1)+'"]')?.focus();if(!cart.length)cartDialog.querySelector('[data-action="continue-shopping"]')?.focus();announce('Item removed from cart');}if(el.dataset.cartDelta){const i=+el.dataset.index;cart[i].qty=Math.max(1,Math.min(99,cart[i].qty+Number(el.dataset.cartDelta)));saveCart();renderCart();cartDialog.querySelector('[data-cart-delta="'+el.dataset.cartDelta+'"][data-index="'+i+'"]')?.focus();}if(el.dataset.action==='continue-shopping'){cartDialog.close();location.hash=link('solutions');}if(el.dataset.action==='checkout')showCheckout();if(el.dataset.action==='view-cart'){cartDialog.close();openContent('Your Cart',cart.map(i=>'<div class="checkout-line"><span>'+esc(getProduct(i.id).name)+' · '+i.color+' × '+i.qty+'</span><strong>'+money(getProduct(i.id).price*i.qty)+'</strong></div>').join('')+'<div class="checkout-line"><strong>Subtotal</strong><strong>'+money(cartTotal())+'</strong></div><button class="button" data-action="back-cart">Edit Cart</button>');}});
cartDialog.addEventListener('change',e=>{if(e.target.dataset.cartQuantity!==undefined){const i=+e.target.dataset.cartQuantity;cart[i].qty=Math.max(1,Math.min(99,Math.round(Number(e.target.value)||1)));saveCart();renderCart();cartDialog.querySelector('[data-cart-quantity="'+i+'"]')?.focus({preventScroll:true});}});
contentDialog.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.matches('[data-close-content]'))contentDialog.close();if(el.dataset.action==='back-cart'){contentDialog.close();openCart();}if(el.dataset.action==='restore-account'){accountSignedOut=false;contentDialog.close();location.hash=link('account');}if(el.tagName==='A'&&el.hash.startsWith('#/'))contentDialog.close();});
contentDialog.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='account-settings'){accountName=document.querySelector('#account-name').value.trim()||'Celine';try{localStorage.setItem('amcrest-demo-name',accountName);}catch{}document.querySelector('#settings-message').textContent='Changes saved in this demo.';if(currentRoute==='account')render();}if(e.target.id==='address-form')document.querySelector('#address-message').textContent='Address preview complete. Nothing has been submitted.';if(e.target.id==='claim-form')document.querySelector('#claim-message').textContent='Request preview complete. No claim has been submitted.';});
for(const d of [cartDialog,contentDialog]){d.addEventListener('close',()=>{if(!cartDialog.open&&!contentDialog.open&&!mobileMenu)document.body.classList.remove('modal-open');});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main').focus();document.querySelector('#main').scrollIntoView();return;}if(navPanel&&!e.target.closest('.header'))closeNav();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(mobileMenu){e.preventDefault();closeMobile();}if(navPanel){closeNav();document.querySelector('[data-action="search-menu"]')?.focus();}}if(e.target.matches('[data-detail-tab]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-detail-tab]')];let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].click();tabs[i].focus();}if(mobileMenu&&e.key==='Tab'){const focusable=[...document.querySelector('#mobile-nav').querySelectorAll('a,button,input,summary')].filter(el=>el.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
let renderedHash=location.hash,scrollPositions=new Map();
window.addEventListener('hashchange',()=>{scrollPositions.set(renderedHash,window.scrollY);if(cartDialog.open)cartDialog.close();if(contentDialog.open)contentDialog.close();document.body.classList.remove('modal-open');render();if(scrollPositions.has(location.hash)){const top=scrollPositions.get(location.hash);requestAnimationFrame(()=>window.scrollTo({top,behavior:'instant'}));}renderedHash=location.hash;});
render();
